#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
runApplication blockMesh
runApplication transformPoints -scale '(1.6666 1 1)'
runApplication -s xplane mirrorMesh -dict system/mirrorMeshDict.X -overwrite
runApplication -s yplane mirrorMesh -dict system/mirrorMeshDict.Y -overwrite
restore0Dir
runApplication topoSet
runApplication createPatch -overwrite
runApplication surfaceMeshExtract \
-patches hole ppGeometry.vtp -constant -time none
echo "End"
#------------------------------------------------------------------------------
cd 切换当前工作目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
transformPoints 平移、旋转或缩放网格坐标，可同步旋转向量与张量场。
mirrorMesh 按字典定义的平面镜像并扩展网格。结果覆盖当前网格。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
topoSet 按几何、网格属性和集合关系创建或修改 sets/zones。
createPatch 把已有边界面或 faceSet 重组为指定 patch。结果覆盖当前网格。
surfaceMeshExtract 从体网格的边界或 faceZone 中提取表面网格。
echo 显示环境变量或简单文本。
